"use client";

import {
  AlertCircle,
  Building2,
  Check,
  CheckCircle2,
  ChevronLeft,
  ChevronRight,
  Loader2,
  Lock,
  Mail,
  ShieldCheck,
  User,
  XCircle,
  type LucideIcon,
} from "lucide-react";
import { useState } from "react";
import { cn } from "@/lib/utils";
import {
  Stepper,
  StepperContent,
} from "@/components/custom/blocks/StepperBlock";
// The Workspace step picks a role with the Select block:
//   npx shadcn@latest add @algorize-ui/select
import { SelectBlock } from "@/components/custom/blocks/SelectBlock";

const PRIMARY_ROLE_OPTIONS = [
  "Developer",
  "Designer",
  "Product Manager",
  "Founder",
].map((r) => ({ label: r, value: r }));

const BACK_BTN =
  "flex items-center gap-1.5 px-4 py-2.5 rounded-xl border border-foreground/10 bg-card text-foreground font-semibold text-sm shadow-[0_1px_2px_rgb(0_0_0/0.04)] disabled:opacity-40 disabled:cursor-not-allowed hover:bg-muted transition-all active:scale-95 cursor-pointer";
const NEXT_BTN =
  "flex items-center gap-1.5 px-6 py-2.5 rounded-xl text-primary-foreground font-semibold text-sm shadow-md transition-all hover:brightness-110 active:scale-95 cursor-pointer bg-primary";

// Controlled field. 'error' is what makes a blocked Next visible to the reader.
function Field({
  label,
  icon: Icon,
  placeholder,
  value,
  onChange,
  error,
  type,
}: {
  label: string;
  icon?: LucideIcon;
  placeholder: string;
  value: string;
  onChange: (next: string) => void;
  error?: string;
  type?: string;
}) {
  return (
    <label className="flex flex-col gap-1.5 w-full">
      <span className="text-xs font-semibold text-foreground uppercase tracking-wider">
        {label} <span className="text-destructive">*</span>
      </span>
      <div className="relative flex items-center">
        {Icon && (
          <div className="absolute left-3.5 text-muted-foreground pointer-events-none">
            <Icon className="w-4 h-4" />
          </div>
        )}
        <input
          type={type}
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder={placeholder}
          className={cn(
            // Focus is a soft primary glow: the border takes the colour and a
            // faint 4px halo fades in with it.
            "w-full h-11 bg-background border rounded-xl px-3.5 text-sm text-foreground placeholder:text-muted-foreground outline-none shadow-[0_1px_2px_rgb(0_0_0/0.04)] transition-[border-color,box-shadow] duration-200 ease-out",
            Icon && "pl-10",
            error
              ? "border-destructive focus:shadow-[0_0_0_4px_color-mix(in_oklab,var(--destructive)_16%,transparent)]"
              : "border-input hover:border-foreground/20 focus:border-primary/65 focus:shadow-[0_0_0_4px_color-mix(in_oklab,var(--primary)_16%,transparent)]",
          )}
        />
      </div>
      {error && (
        <span className="flex items-center gap-1 text-xs font-semibold text-destructive mt-0.5">
          <AlertCircle className="w-3.5 h-3.5 flex-shrink-0" />
          {error}
        </span>
      )}
    </label>
  );
}

// Every step body sits on this card — it is what the preview renders.
function StepCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full p-6 sm:p-8 bg-card text-card-foreground rounded-2xl border border-foreground/[0.06] shadow-[0_1px_2px_rgb(0_0_0/0.04),0_8px_24px_-12px_rgb(0_0_0/0.12)] flex flex-col gap-5">
      <div>
        <h3 className="text-lg font-semibold text-foreground">{title}</h3>
        <p className="text-xs text-muted-foreground">{subtitle}</p>
      </div>
      {children}
    </div>
  );
}

type FormData = {
  fullName: string;
  email: string;
  company: string;
  role: string;
  password: string;
  confirmPassword: string;
};
type Errors = Partial<Record<keyof FormData, string>>;

export default function OnboardingWizard() {
  const [step, setStep] = useState(0);
  const [formData, setFormData] = useState<FormData>({
    fullName: "",
    email: "",
    company: "",
    role: "Developer",
    password: "",
    confirmPassword: "",
  });
  const [errors, setErrors] = useState<Errors>({});
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [simulateError, setSimulateError] = useState(false);
  const [submitError, setSubmitError] = useState("");

  const set = (key: keyof FormData) => (next: string) =>
    setFormData((prev) => ({ ...prev, [key]: next }));

  // Returns false AND records the reason, so the blocked step explains itself.
  const validateStep = (current: number) => {
    const next: Errors = {};
    if (current === 0 && !formData.fullName) next.fullName = "Name required";
    if (current === 1 && !formData.company) next.company = "Company required";
    if (current === 2 && !formData.password) next.password = "Password required";
    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const handleNext = () => {
    if (validateStep(step)) setStep((s) => s + 1);
  };

  const handleSubmit = async () => {
    setIsSubmitting(true);
    setSubmitError("");
    try {
      // simulateError is the preview's DEBUG_MODE switch — it lets you see the
      // failure branch without breaking the endpoint. Drop it in your own app.
      if (simulateError) throw new Error("ERR_500: Database insertion failed.");
      await fetch("/api/submit", {
        method: "POST",
        body: JSON.stringify(formData),
      });
    } catch (e) {
      setSubmitError(e instanceof Error ? e.message : "Submission failed");
    } finally {
      setIsSubmitting(false);
    }
  };

  const steps = [
    {
      id: "profile",
      title: "Profile",
      description: "Personal details",
      icon: User,
      content: (
        <StepCard title="Personal Information" subtitle="Enter your contact details to begin setting up your account.">
          <div className="grid gap-4 sm:grid-cols-2">
            <Field
              label="Full Name"
              icon={User}
              placeholder="e.g. Alex Rivera"
              value={formData.fullName}
              onChange={set("fullName")}
              error={errors.fullName}
            />
            <Field
              label="Work Email"
              icon={Mail}
              type="email"
              placeholder="alex@company.com"
              value={formData.email}
              onChange={set("email")}
            />
          </div>
        </StepCard>
      ),
    },
    {
      id: "workspace",
      title: "Workspace",
      description: "Organization",
      icon: Building2,
      content: (
        <StepCard title="Workspace Setup" subtitle="Name your organization and select your primary role.">
          <div className="grid gap-4 sm:grid-cols-2">
            <Field
              label="Company Name"
              icon={Building2}
              placeholder="e.g. Acme Corp"
              value={formData.company}
              onChange={set("company")}
              error={errors.company}
            />
            <div className="flex flex-col gap-1.5 w-full">
              <label className="text-xs font-semibold text-foreground uppercase tracking-wider">
                Primary Role
              </label>
              <SelectBlock
                options={PRIMARY_ROLE_OPTIONS}
                value={formData.role}
                onChange={set("role")}
                variant="default"
                placeholder="Select your role"
              />
            </div>
          </div>
        </StepCard>
      ),
    },
    {
      id: "security",
      title: "Security",
      description: "Credentials",
      icon: ShieldCheck,
      content: (
        <StepCard title="Security Credentials" subtitle="Create a secure password for your workspace access.">
          <div className="grid gap-4 sm:grid-cols-2">
            <Field
              label="Password"
              icon={Lock}
              type="password"
              placeholder="Min 6 characters"
              value={formData.password}
              onChange={set("password")}
              error={errors.password}
            />
            <Field
              label="Confirm Password"
              icon={Lock}
              type="password"
              placeholder="Re-type password"
              value={formData.confirmPassword}
              onChange={set("confirmPassword")}
            />
          </div>
        </StepCard>
      ),
    },
    {
      id: "review",
      title: "Review",
      description: "Confirm & Submit",
      icon: CheckCircle2,
      content: (
        <StepCard title="Review Summary" subtitle="Please verify your details before submitting the onboarding payload.">
          <div className="grid grid-cols-2 gap-4 bg-muted/50 p-4 rounded-xl border border-border text-xs">
            <div>
              <span className="text-muted-foreground block font-semibold">Name:</span>
              <span className="font-semibold text-foreground text-sm">{formData.fullName || "—"}</span>
            </div>
            <div>
              <span className="text-muted-foreground block font-semibold">Email:</span>
              <span className="font-semibold text-foreground text-sm truncate block">{formData.email || "—"}</span>
            </div>
            <div>
              <span className="text-muted-foreground block font-semibold">Company:</span>
              <span className="font-semibold text-foreground text-sm">{formData.company || "—"}</span>
            </div>
            <div>
              <span className="text-muted-foreground block font-semibold">Role:</span>
              <span className="font-semibold text-foreground text-sm">{formData.role || "—"}</span>
            </div>
          </div>

          {submitError && (
            <div className="p-4 bg-destructive/10 border border-destructive/30 rounded-xl flex items-start gap-3 text-destructive">
              <XCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />
              <div className="text-xs">
                <strong className="font-semibold block mb-0.5">Submission Failed</strong>
                <span>{submitError}</span>
              </div>
            </div>
          )}

          <div className="pt-2 border-t border-border flex items-center justify-between">
            <label className="flex items-center gap-2 cursor-pointer select-none text-xs font-semibold text-muted-foreground">
              <input
                type="checkbox"
                checked={simulateError}
                onChange={(e) => setSimulateError(e.target.checked)}
                className="rounded border-input accent-primary"
              />
              Simulate Server Error on Submit
            </label>
            <span className="text-[10px] text-muted-foreground font-mono">DEBUG_MODE</span>
          </div>
        </StepCard>
      ),
    },
  ];

  return (
    // A whisper of the primary on the shell separates it from a white page;
    // the white step cards float on it.
    <div className="max-w-3xl mx-auto flex flex-col gap-8 rounded-3xl p-6 sm:p-10 border bg-[oklch(from_var(--primary)_0.975_calc(c*0.12)_h)] border-[oklch(from_var(--primary)_0.91_calc(c*0.2)_h)] dark:bg-[oklch(from_var(--primary)_0.21_calc(c*0.1)_h)] dark:border-foreground/10 shadow-[0_1px_2px_rgb(0_0_0/0.04),0_20px_48px_-20px_rgb(0_0_0/0.18)]">
      {/* onStepChange is what makes the circles clickable — gate it on validation */}
      <Stepper
        steps={steps}
        currentStep={step}
        onStepChange={(target) => {
          if (target < step || validateStep(step)) setStep(target);
        }}
      />

      <StepperContent steps={steps} currentStep={step} />

      <div className="flex items-center justify-between pt-6 border-t border-border">
        <button
          type="button"
          onClick={() => setStep((s) => s - 1)}
          disabled={step === 0 || isSubmitting}
          className={BACK_BTN}
        >
          <ChevronLeft className="w-4 h-4" />
          Back
        </button>

        {step === steps.length - 1 ? (
          <button
            type="button"
            onClick={handleSubmit}
            disabled={isSubmitting}
            className={NEXT_BTN}
          >
            {isSubmitting ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                <span>Submitting...</span>
              </>
            ) : (
              <>
                <span>Submit Onboarding</span>
                <Check className="w-4 h-4 stroke-[3]" />
              </>
            )}
          </button>
        ) : (
          <button type="button" onClick={handleNext} className={NEXT_BTN}>
            <span>Next Step</span>
            <ChevronRight className="w-4 h-4" />
          </button>
        )}
      </div>
    </div>
  );
}

"use client";

import { cn } from "@/lib/utils";
import { Check } from "lucide-react";
import React, { useEffect, useRef } from "react";

// ==========================================
// TYPES & INTERFACES
// ==========================================
export interface Step {
  id: string;
  title: string;
  description?: string;
  icon?: React.ElementType;
  content?: React.ReactNode;
}

export interface StepperProps extends React.HTMLAttributes<HTMLDivElement> {
  steps: Step[];
  currentStep: number;
  onStepChange?: (step: number) => void;
  /** Any CSS color (hex, rgb/hsl/oklch, var(--token)) or a Tailwind bg class. */
  color?: string;
}

/**
 * A raw CSS color is applied inline; anything else is assumed to be a Tailwind
 * class the consumer already has in their build. Inline is the richer path —
 * the pulse ring needs a border color, and a `border-*` class derived at
 * runtime would never be seen by Tailwind's scanner.
 */
const isCssColorValue = (color: string) =>
  /^(#|rgb|hsl|oklch|lab|lch|color\(|var\()/.test(color.trim());

// ==========================================
// MOTION CURVES (CSS easings)
// ==========================================
/** power3.inOut, sampled into a CSS `linear()` curve. */
const EASE_POWER3_IN_OUT =
  "linear(0, 0, 0, .0001, .0002, .0004, .0008, .0015, .0025, .0041, .0062, .009, .0128, .0176, .0237, .0313, .0405, .0516, .0648, .0804, .0988, .12, .1446, .1727, .2048, .2411, .2821, .3281, .3794, .4366, .5, .5634, .6206, .672, .7179, .7589, .7952, .8273, .8554, .88, .9012, .9196, .9352, .9484, .9595, .9688, .9763, .9824, .9872, .991, .9938, .996, .9975, .9985, .9992, .9996, .9998, 1, 1, 1, 1)";
/** power3.out, sampled into a CSS `linear()` curve. */
const EASE_POWER3_OUT =
  "linear(0, .0963, .1855, .2679, .3439, .4138, .478, .5367, .5904, .6392, .6836, .7237, .7599, .7924, .8215, .8474, .8704, .8907, .9085, .924, .9375, .9491, .959, .9674, .9744, .9802, .985, .9888, .9919, .9943, .9961, .9974, .9984, .9991, .9995, .9998, .9999, 1, 1, 1, 1)";
/** back.out(2.5) is a cubic, so this bezier is exact. */
const EASE_BACK_OUT = "cubic-bezier(0.3333, 1.8333, 0.6667, 1)";
/** power2.out, exact. */
const EASE_POWER2_OUT = "cubic-bezier(0.3333, 1, 0.6667, 1)";

// ==========================================
// STEPPER NAVIGATION HEADER (CSS transitions)
// ==========================================
export const Stepper = React.forwardRef<HTMLDivElement, StepperProps>(
  (
    {
      steps,
      currentStep,
      onStepChange,
      color = "var(--primary)",
      className,
      ...props
    },
    ref,
  ) => {
    const progressRef = useRef<HTMLDivElement>(null);
    const progressPlaced = useRef(false);
    // A single step has no line to fill (and would divide by zero).
    const progress = steps.length > 1 ? currentStep / (steps.length - 1) : 0;
    const isCssColor = isCssColorValue(color);

    // Progress Line Animation — grows from the `scale-x-0` rest state on
    // mount, then from wherever it is to each new step.
    useEffect(() => {
      const el = progressRef.current;
      if (!el) return;
      // Settle the starting style first so the very first change transitions.
      if (!progressPlaced.current) {
        void el.offsetWidth;
        progressPlaced.current = true;
      }
      el.style.transition = `scale 0.5s ${EASE_POWER3_IN_OUT}`;
      el.style.scale = `${progress} 1`;
    }, [progress]);

    return (
      <div ref={ref} className={cn("relative w-full", className)} {...props}>
        <style>{`
          @keyframes stepper-pulse-ring {
            from { transform: scale(1); opacity: 0.8; }
            to { transform: scale(1.45); opacity: 0; }
          }
        `}</style>

        {/* Background Track Line — sits on the circle centre (16px on mobile, 20px from sm up) */}
        <div className="absolute top-4 sm:top-5 left-0 w-full h-[2px] bg-muted -translate-y-1/2 z-0 rounded-full overflow-hidden">
          {/* Animated Foreground Progress Line */}
          <div
            ref={progressRef}
            className={cn(
              "absolute top-0 left-0 w-full h-full origin-left scale-x-0",
              !isCssColor && color,
            )}
            style={{ backgroundColor: isCssColor ? color : undefined }}
          />
        </div>

        {/* Step Indicators */}
        <div className="relative z-10 flex justify-between w-full">
          {steps.map((step, index) => {
            const isCompleted = currentStep > index;
            const isActive = currentStep === index;

            return (
              <div
                key={step.id}
                className="flex flex-col items-center group relative min-w-0 px-1 sm:px-1.5"
                style={{ width: `${100 / steps.length}%` }}
              >
                {/* Clickable Area (Now unlocked for ALL steps) */}
                <button
                  type="button"
                  onClick={() => onStepChange?.(index)}
                  disabled={!onStepChange}
                  className={cn(
                    "relative flex items-center justify-center w-8 h-8 sm:w-10 sm:h-10 shrink-0 rounded-full border-2 transition-colors duration-300 outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
                    isCompleted || isActive
                      ? cn("border-transparent text-primary-foreground", !isCssColor && color)
                      : "border-border bg-card text-muted-foreground",
                    onStepChange
                      ? "cursor-pointer hover:scale-110 active:scale-95"
                      : "cursor-default",
                  )}
                  style={{
                    backgroundColor:
                      (isCompleted || isActive) && isCssColor
                        ? color
                        : undefined,
                  }}
                >
                  {/* Dynamic Inner Content with Pop */}
                  <StepIndicatorContent
                    isCompleted={isCompleted}
                    isActive={isActive}
                    index={index}
                    icon={step.icon}
                  />

                  {/* Active Ring Pulse Effect (CSS keyframes) */}
                  {isActive && isCssColor && <PulseRing color={color} />}
                </button>

                {/* Step Text */}
                <div className="mt-1.5 sm:mt-3 text-center flex flex-col items-center w-full min-w-0">
                  <span
                    className={cn(
                      "text-[11px] sm:text-sm font-semibold leading-tight break-words hyphens-auto transition-colors duration-300",
                      isActive || isCompleted
                        ? "text-foreground"
                        : "text-muted-foreground",
                    )}
                  >
                    {step.title}
                  </span>
                  {step.description && (
                    <span className="text-[11px] font-medium text-muted-foreground hidden sm:block mt-0.5 max-w-[120px] leading-tight">
                      {step.description}
                    </span>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  },
);
Stepper.displayName = "Stepper";

// ==========================================
// HELPER: STEP ICON POP ANIMATION
// ==========================================
interface StepIndicatorContentProps {
  isCompleted: boolean;
  isActive: boolean;
  index: number;
  icon?: React.ElementType;
}

const StepIndicatorContent = ({
  isCompleted,
  isActive,
  index,
  icon: Icon,
}: StepIndicatorContentProps) => {
  const contentRef = useRef<HTMLDivElement>(null);
  const popRef = useRef<Animation | null>(null);

  useEffect(() => {
    const el = contentRef.current;
    if (!el) return;
    popRef.current?.cancel();
    popRef.current = el.animate(
      [
        { transform: "scale(0.3)", opacity: 0 },
        { transform: "scale(1)", opacity: 1 },
      ],
      { duration: 400, easing: EASE_BACK_OUT },
    );
  }, [isCompleted, isActive]);

  if (isCompleted) {
    return (
      <div ref={contentRef} className="flex items-center justify-center">
        <Check className="w-4 h-4 sm:w-5 sm:h-5 stroke-[3]" />
      </div>
    );
  }

  return (
    <div
      ref={contentRef}
      className="font-semibold text-xs sm:text-sm flex items-center justify-center"
    >
      {Icon ? <Icon className="w-4 h-4 sm:w-5 sm:h-5" /> : index + 1}
    </div>
  );
};

// ==========================================
// HELPER: CONTINUOUS RING PULSE
// ==========================================
const PulseRing = ({ color }: { color: string }) => {
  return (
    <div
      className="absolute inset-0 rounded-full border-2 pointer-events-none"
      style={{
        borderColor: color,
        animation: `stepper-pulse-ring 1.5s ${EASE_POWER2_OUT} infinite`,
      }}
    />
  );
};

// ==========================================
// STEPPER CONTENT VIEW (Sliding Transitions)
// ==========================================
export interface StepperContentProps
  extends React.HTMLAttributes<HTMLDivElement> {
  steps: Step[];
  currentStep: number;
}

export const StepperContent = React.forwardRef<
  HTMLDivElement,
  StepperContentProps
>(({ steps, currentStep, className, ...props }, ref) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const prevStepRef = useRef(currentStep);

  React.useImperativeHandle(ref, () => containerRef.current as HTMLDivElement);

  useEffect(() => {
    if (!containerRef.current) return;
    const dir = currentStep >= prevStepRef.current ? 1 : -1;
    prevStepRef.current = currentStep;

    // Animate slide-in
    const animations = Array.from(containerRef.current.children, (child) =>
      child.animate(
        [
          { transform: `translateX(${45 * dir}px) scale(0.98)`, opacity: 0 },
          { transform: "translateX(0px) scale(1)", opacity: 1 },
        ],
        { duration: 450, easing: EASE_POWER3_OUT },
      ),
    );
    return () => animations.forEach((animation) => animation.cancel());
  }, [currentStep]);

  return (
    <div
      ref={containerRef}
      // overflow-x-clip, not overflow-hidden: the clip is only there to hide
      // the 45px sideways slide-in. Hidden on both axes also cropped anything
      // a step hangs below itself — a select's menu, an autocomplete list.
      className={cn("relative w-full overflow-x-clip", className)}
      {...props}
    >
      {/* Key change triggers React to swap DOM nodes cleanly for the slide-in */}
      <div key={currentStep} className="w-full">
        {steps[currentStep]?.content}
      </div>
    </div>
  );
});
StepperContent.displayName = "StepperContent";

"use client";

import { cn } from "@/lib/utils";
import { AlertCircle, Check, ChevronDown, Search, X } from "lucide-react";
import React, { forwardRef, useEffect, useMemo, useRef, useState } from "react";
import { getThemeStyles } from "./select-theme";

// ==========================================
// DYNAMIC THEME ENGINE
// ==========================================
export type SelectColor = "indigo" | "rose" | "emerald" | "zinc" | string;
export type SelectVariant = "default" | "filled" | "underlined" | "glow" | "glass";
export type SelectSize = "sm" | "md" | "lg";

// ==========================================
// SELECT COMPONENT
// ==========================================
export interface SelectOption {
  label: string;
  value: string;
  icon?: React.ElementType;
  group?: string; // Added for nested/grouped options
}

// Walks up the tree to the first ancestor that clips its overflow (a modal
// shell, a scroll pane, a card with overflow-hidden). That element — not the
// viewport — is what actually crops the dropdown, so it defines the space the
// menu has to work with. Returns null when nothing clips, meaning the viewport
// is the only bound. Only overflow-y counts: the menu grows vertically, and a
// box that clips just sideways (overflow-x: clip, e.g. a slide-in stage) leaves
// it free to hang below — treating that as a clip flipped the menu up into it.
const getClippingRect = (el: HTMLElement): DOMRect | null => {
  let node = el.parentElement;
  while (node && node !== document.body) {
    const { overflowY } = window.getComputedStyle(node);
    if (/(auto|scroll|hidden|clip)/.test(overflowY)) {
      return node.getBoundingClientRect();
    }
    node = node.parentElement;
  }
  return null;
};

/** Everything the two selection modes share. */
interface SelectBlockBaseProps {
  options: SelectOption[];
  placeholder?: string;
  variant?: SelectVariant;
  color?: SelectColor;
  inputSize?: SelectSize;
  label?: string;
  helperText?: string;
  error?: string;
  icon?: React.ReactNode;
  disabled?: boolean;
  className?: string;
  /** Adds a filter box above the options. */
  searchable?: boolean;
}

/** The default: one option at a time, so the value is a plain string. */
export interface SelectBlockSingleProps extends SelectBlockBaseProps {
  multiple?: false;
  value?: string;
  onChange?: (value: string) => void;
}

/** `multiple` — value and callback both deal in arrays. */
export interface SelectBlockMultipleProps extends SelectBlockBaseProps {
  multiple: true;
  value?: string[];
  onChange?: (value: string[]) => void;
}

/**
 * Discriminated on `multiple`, so a single select hands your callback a
 * `string` and a multi select hands it a `string[]` — neither needs a cast,
 * and passing a `setState` straight in just works.
 */
export type SelectBlockProps = SelectBlockSingleProps | SelectBlockMultipleProps;

/** The two modes collapsed, which is what the implementation works with. */
type SelectBlockImplProps = SelectBlockBaseProps & {
  multiple?: boolean;
  value?: string | string[];
  onChange?: (value: string | string[]) => void;
};

const SelectBlockImpl = forwardRef<HTMLDivElement, SelectBlockImplProps>(
  (
    {
      options = [],
      value,
      onChange,
      placeholder = "Select an option",
      variant = "default",
      color = "primary",
      inputSize = "md",
      label,
      helperText,
      error,
      icon,
      disabled = false,
      className,
      multiple = false,
      searchable = false,
    },
    ref,
  ) => {
    const [isOpen, setIsOpen] = useState(false);
    const [dropUp, setDropUp] = useState(false);
    const [searchQuery, setSearchQuery] = useState("");
    const selectRef = useRef<HTMLDivElement>(null);
    const dropdownRef = useRef<HTMLDivElement>(null);
    const searchInputRef = useRef<HTMLInputElement>(null);
    const { theme, style } = getThemeStyles(color);

    // selectRef drives the click-outside and drop-direction logic, so the
    // forwarded ref is mirrored onto it rather than replacing it.
    React.useImperativeHandle(ref, () => selectRef.current as HTMLDivElement);

    const hasError = Boolean(error);

    // Filter options based on search
    const filteredOptions = useMemo(() => {
      if (!searchQuery) return options;
      return options.filter((opt) =>
        opt.label.toLowerCase().includes(searchQuery.toLowerCase()),
      );
    }, [options, searchQuery]);

    // Group options if "group" property is provided
    const groupedOptions = useMemo(() => {
      return filteredOptions.reduce(
        (acc, opt) => {
          const group = opt.group || "ungrouped";
          if (!acc[group]) acc[group] = [];
          acc[group].push(opt);
          return acc;
        },
        {} as Record<string, SelectOption[]>,
      );
    }, [filteredOptions]);

    // Focus search input automatically when opened
    useEffect(() => {
      if (isOpen && searchable && searchInputRef.current) {
        setTimeout(() => searchInputRef.current?.focus(), 50);
      }
      if (!isOpen) setSearchQuery("");
    }, [isOpen, searchable]);

    // Close dropdown on click outside
    useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
        if (
          selectRef.current &&
          !selectRef.current.contains(event.target as Node)
        ) {
          setIsOpen(false);
        }
      };
      document.addEventListener("mousedown", handleClickOutside);
      return () =>
        document.removeEventListener("mousedown", handleClickOutside);
    }, []);

    // Decide which way the menu opens *before* it becomes visible, so it never
    // renders in the wrong place for a frame. The menu is always mounted (it is
    // only hidden via opacity), so its height is measurable while closed.
    const handleToggle = () => {
      if (!isOpen && selectRef.current) {
        const trigger = selectRef.current.getBoundingClientRect();
        const clip = getClippingRect(selectRef.current);
        const menuHeight = dropdownRef.current?.offsetHeight ?? 240;

        const bottomBound = Math.min(
          window.innerHeight,
          clip ? clip.bottom : Number.POSITIVE_INFINITY,
        );
        const topBound = Math.max(0, clip ? clip.top : 0);

        const spaceBelow = bottomBound - trigger.bottom - 8;
        const spaceAbove = trigger.top - topBound - 8;

        // Only flip when below genuinely can't fit and above is roomier.
        setDropUp(spaceBelow < menuHeight && spaceAbove > spaceBelow);
      }
      setIsOpen(!isOpen);
    };

    const handleSelect = (optValue: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (multiple) {
        const currentValues = Array.isArray(value) ? value : [];
        const newValues = currentValues.includes(optValue)
          ? currentValues.filter((v) => v !== optValue)
          : [...currentValues, optValue];
        if (onChange) onChange(newValues);
      } else {
        if (onChange) onChange(optValue);
        setIsOpen(false);
      }
    };

    const handleRemoveTag = (optValue: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (multiple && Array.isArray(value)) {
        if (onChange) onChange(value.filter((v) => v !== optValue));
      }
    };

    // --- Size Classes ---
    const sizeClasses = {
      sm: {
        wrapper: "min-h-9 px-3 py-1.5",
        text: "text-xs",
        icon: "w-3.5 h-3.5",
        option: "px-3 py-2 text-xs",
        tag: "px-1.5 py-0.5 text-[10px]",
      },
      md: {
        wrapper: "min-h-11 px-4 py-2.5",
        text: "text-sm",
        icon: "w-4 h-4",
        option: "px-4 py-2.5 text-sm",
        tag: "px-2 py-1 text-xs",
      },
      lg: {
        wrapper: "min-h-14 px-5 py-3.5",
        text: "text-base",
        icon: "w-5 h-5",
        option: "px-5 py-3 text-base",
        tag: "px-2.5 py-1 text-sm",
      },
    };
    const s = sizeClasses[inputSize];

    // --- Variant Styles ---
    const getVariantStyles = () => {
      const baseWrapper = cn(
        "relative flex items-center justify-between w-full transition-all duration-300 cursor-pointer outline-none",
        s.wrapper,
      );

      if (disabled)
        return {
          wrapper: cn(
            baseWrapper,
            "opacity-50 cursor-not-allowed border border-border bg-muted",
          ),
          active: "",
        };
      if (hasError)
        return {
          wrapper: cn(
            baseWrapper,
            "border border-red-500 bg-background",
            variant === "underlined" && "border-0 border-b-2 rounded-none",
            variant !== "underlined" && "rounded-xl",
          ),
          active: "ring-4 ring-red-500/10",
        };

      switch (variant) {
        case "filled":
          return {
            wrapper: cn(
              baseWrapper,
              "bg-muted border border-transparent rounded-xl",
            ),
            active: cn("bg-background ring-4", theme.ring),
          };
        case "underlined":
          return {
            wrapper: cn(
              baseWrapper,
              "border-b-2 border-border bg-transparent rounded-none px-0",
            ),
            active: theme.ring.split(" ")[1],
          };
        case "glow":
          return {
            wrapper: cn(
              baseWrapper,
              "bg-background border border-border rounded-xl shadow-sm",
            ),
            active: theme.glow,
          };
        case "glass":
          return {
            wrapper: cn(
              baseWrapper,
              "min-h-[38px] px-3 py-2 text-sm border-black/15 text-neutral-900 bg-black/5 hover:bg-black/10 focus:bg-white/40 focus:border-black/30 dark:border-white/25 dark:text-white dark:bg-white/10 dark:hover:bg-white/15 dark:focus:bg-white/20 dark:focus:border-white/50 border rounded-md shadow-xs transition-all",
            ),
            active: "ring-2 ring-black/10 dark:ring-white/20 border-black/30 dark:border-white/40 bg-black/10 dark:bg-white/15",
          };
        case "default":
        default:
          return {
            wrapper: cn(
              baseWrapper,
              "bg-background border border-border rounded-xl shadow-sm",
            ),
            active: cn("ring-4", theme.ring),
          };
      }
    };

    const styles = getVariantStyles();

    // Renders the selected content (Tags for multi, text for single)
    const renderSelectedContent = () => {
      if (multiple && Array.isArray(value) && value.length > 0) {
        return (
          <div className="flex flex-wrap items-center gap-1.5 w-full pr-6 overflow-hidden">
            {value.map((val) => {
              const opt = options.find((o) => o.value === val);
              if (!opt) return null;
              return (
                <span
                  key={val}
                  onClick={(e) => handleRemoveTag(val, e)}
                  className={cn(
                    "inline-flex items-center gap-1 font-semibold rounded-md border border-transparent hover:border-red-200 dark:hover:border-red-900 transition-colors",
                    s.tag,
                    theme.bgSoft,
                  )}
                >
                  {opt.label}
                  <X
                    className={cn("shrink-0 hover:text-red-500", s.icon)}
                    style={{ width: "0.8em", height: "0.8em" }}
                  />
                </span>
              );
            })}
          </div>
        );
      }

      const singleOption = options.find((opt) => opt.value === value);
      return (
        <span
          className={cn(
            "truncate pr-6",
            s.text,
            !singleOption
              ? variant === "glass" ? "text-neutral-500 dark:text-white/60" : "text-muted-foreground"
              : variant === "glass" ? "text-neutral-900 font-medium dark:text-white" : "text-foreground",
          )}
        >
          {singleOption ? singleOption.label : placeholder}
        </span>
      );
    };

    return (
      <div
        ref={selectRef}
        className={cn("flex flex-col gap-1.5 w-full relative", className)}
        style={style}
      >
        {label && (
          <label
            className={cn(
              "text-sm font-semibold",
              hasError ? "text-red-500" : variant === "glass" ? "text-white/90" : "text-foreground",
              disabled && "opacity-50",
            )}
          >
            {label}
          </label>
        )}

        {/* Trigger Button */}
        <button
          type="button"
          disabled={disabled}
          onClick={handleToggle}
          className={cn(
            styles.wrapper,
            isOpen && styles.active,
            multiple && Array.isArray(value) && value.length > 0 && "py-1.5",
          )}
        >
          <div className="flex items-center gap-2 overflow-hidden w-full">
            {icon && (
              <div
                className={cn(
                  "shrink-0 text-muted-foreground",
                  isOpen && theme.text,
                )}
              >
                {icon}
              </div>
            )}
            {renderSelectedContent()}
          </div>

          <div className="absolute right-4 flex items-center gap-2 shrink-0 bg-transparent">
            {hasError && <AlertCircle className={cn(s.icon, "text-red-500")} />}
            <ChevronDown
              className={cn(
                s.icon,
                variant === "glass" ? "text-neutral-700 dark:text-white/70" : "text-muted-foreground",
                "transition-transform duration-300",
                isOpen && "rotate-180",
                isOpen && theme.text,
              )}
            />
          </div>
        </button>

        {/* Dropdown Menu */}
        <div
          ref={dropdownRef}
          className={cn(
            "absolute left-0 right-0 z-50 overflow-hidden border rounded-xl shadow-2xl transition-all duration-200 ease-out",
            variant === "glass"
              ? "bg-white/50 dark:bg-black/60 backdrop-blur-3xl border border-white/50 dark:border-white/20 text-neutral-900 dark:text-white shadow-2xl"
              : "bg-popover text-popover-foreground border-border",
            dropUp
              ? cn(
                  "origin-bottom",
                  variant === "underlined"
                    ? "bottom-[100%]"
                    : "bottom-[calc(100%+8px)]",
                )
              : cn(
                  "origin-top",
                  variant === "underlined"
                    ? "top-[100%]"
                    : "top-[calc(100%+8px)]",
                ),
            isOpen
              ? "opacity-100 scale-y-100 translate-y-0 pointer-events-auto"
              : cn(
                  "opacity-0 scale-y-95 pointer-events-none",
                  dropUp ? "translate-y-2" : "-translate-y-2",
                ),
          )}
        >
          {searchable && (
            <div className="p-2 border-b border-border bg-muted/50">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
                <input
                  ref={searchInputRef}
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  onClick={(e) => e.stopPropagation()}
                  placeholder="Search options..."
                  className="w-full pl-9 pr-3 py-2 bg-card border border-border rounded-lg text-sm text-foreground outline-none focus:ring-2 focus:border-transparent transition-all"
                  style={{ "--tw-ring-color": `var(--theme-color)` } as React.CSSProperties}
                />
              </div>
            </div>
          )}

          <div className="max-h-60 overflow-y-auto p-1 flex flex-col gap-0.5 scrollbar-thin scrollbar-thumb-border">
            {Object.keys(groupedOptions).length === 0 ? (
              <div className="px-4 py-3 text-sm text-muted-foreground text-center">
                No results found
              </div>
            ) : (
              Object.entries(groupedOptions).map(([group, opts]) => (
                <div key={group} className="flex flex-col gap-0.5">
                  {/* Group Header */}
                  {group !== "ungrouped" && (
                    <div className="px-3 py-2 mt-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">
                      {group}
                    </div>
                  )}
                  {/* Options */}
                  {opts.map((opt) => {
                    const isSelected =
                      multiple && Array.isArray(value)
                        ? value.includes(opt.value)
                        : value === opt.value;
                    const OptIcon = opt.icon;
                    return (
                      <button
                        key={opt.value}
                        type="button"
                        onClick={(e) => handleSelect(opt.value, e)}
                        className={cn(
                          "w-full flex items-center justify-between rounded-lg transition-colors font-medium text-left cursor-pointer active:scale-[0.98]",
                          s.option,
                          isSelected
                            ? cn(theme.bgSoft, theme.text, "font-semibold shadow-xs")
                            : cn(
                                variant === "glass"
                                  ? "text-neutral-900 dark:text-white/90"
                                  : "text-foreground",
                                theme.hoverBg,
                              ),
                        )}
                      >
                        <div className="flex items-center gap-2">
                          {multiple && (
                            <div
                              className={cn(
                                "w-4 h-4 rounded-[4px] border flex items-center justify-center transition-colors",
                                isSelected
                                  ? cn(theme.bg, "border-transparent")
                                  : "border-input bg-card",
                              )}
                            >
                              {/* No hardcoded colour: theme.bg already carries the
                                  correct contrasting text colour for each theme
                                  (text-white for indigo/rose/hex, but
                                  text-primary-foreground for "primary", which
                                  inverts in dark mode). */}
                              {isSelected && (
                                <Check className="w-3 h-3" strokeWidth={3} />
                              )}
                            </div>
                          )}
                          {OptIcon && <OptIcon className={s.icon} />}
                          <span>{opt.label}</span>
                        </div>
                        {isSelected && !multiple && (
                          <Check
                            className={cn(s.icon, theme.text)}
                            strokeWidth={3}
                          />
                        )}
                      </button>
                    );
                  })}
                </div>
              ))
            )}
          </div>
        </div>

        {error && (
          <p className="text-xs font-semibold text-red-500 flex items-center gap-1 mt-0.5">
            <AlertCircle className="w-3.5 h-3.5" /> {error}
          </p>
        )}
        {helperText && !error && (
          <p className="text-xs font-medium text-muted-foreground mt-0.5">
            {helperText}
          </p>
        )}
      </div>
    );
  },
);
SelectBlockImpl.displayName = "SelectBlock";

/**
 * The implementation is written against the collapsed props; this cast is
 * what hands callers the discriminated pair instead.
 */
export const SelectBlock = SelectBlockImpl as React.ForwardRefExoticComponent<
  SelectBlockProps & React.RefAttributes<HTMLDivElement>
>;

